/* Penyelesaian penuh UKKM Set 2: Matematik & Sains (dimuat selepas kertas dihantar) */
(window.UKKM_SOL = window.UKKM_SOL || {})[2] = {"mat":["<h5>🧭 Faham soalan</h5><p>Jujukan bermula dengan 2, 5, 10, 17 dan 26. Kita perlu mencari sebutan selepas 26.</p><h5>💡 Strategi</h5><p>Cari beza antara sebutan berturutan. Beza yang membentuk pola lebih mudah dilanjutkan daripada nombor asal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Beza pertama: 5 − 2 = 3; beza kedua: 10 − 5 = 5.</li><li>Beza seterusnya: 17 − 10 = 7 dan 26 − 17 = 9.</li><li>Beza bertambah 2 setiap kali, maka beza baharu ialah 9 + 2 = 11. Sebutan seterusnya ialah 26 + 11 = 37.</li><li>Jawapan: <b>C</b> (37).</li></ol><h5>🔍 Semak jawapan</h5><p>Semakan lain: sebutan ke-n ialah n² + 1. Sebutan keenam ialah 6² + 1 = 36 + 1 = 37.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (35): 35 datang daripada menambah 9 sekali lagi, sedangkan beza seterusnya 11.</li><li><b>B</b> (36): 36 ialah 6² sahaja; pola ini memerlukan tambahan 1.</li><li><b>D</b> (39): 39 bermaksud menambah 13 kepada 26, iaitu melangkau beza 11.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tulis beza di bawah setiap pasangan sebutan sebelum meneka pola.</p>",
"<h5>🧭 Faham soalan</h5><p>Satu nombor didarab 4, ditolak 6, kemudian dibahagi 2 sehingga hasilnya 15. Nombor asal diminta.</p><h5>💡 Strategi</h5><p>Gunakan operasi songsang mengikut tertib terbalik. Ini membatalkan setiap langkah yang dibuat pada nombor asal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Mula dengan hasil akhir 15. Songsangkan bahagi 2: 15 × 2 = 30.</li><li>Songsangkan tolak 6: 30 + 6 = 36.</li><li>Songsangkan darab 4: 36 ÷ 4 = 9.</li><li>Jawapan: <b>A</b> (9).</li></ol><h5>🔍 Semak jawapan</h5><p>Gantikan 9 ke dalam arahan: 9 × 4 = 36; 36 − 6 = 30; 30 ÷ 2 = 15.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (6): 6 diperoleh jika 30 ditolak 6, sedangkan langkah songsang perlu menambah 6.</li><li><b>C</b> (5.25): 5.25 diperoleh daripada (15 + 6) ÷ 4; langkah bahagi 2 belum disongsangkan.</li><li><b>D</b> (3.75): 3.75 ialah 15 ÷ 4, lalu mengabaikan dua operasi lain.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi soalan proses berantai, mula pada hasil akhir dan songsangkan operasi satu demi satu.</p>",
"<h5>🧭 Faham soalan</h5><p>Harga asal ikan ialah RM 16 sekilogram dan harga baharu RM 20. Kita cari peratus kenaikan berbanding harga asal.</p><h5>💡 Strategi</h5><p>Peratus kenaikan ialah kenaikan harga dibahagi harga asal, kemudian didarab 100%. Penyebut mesti harga sebelum perubahan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kenaikan harga = RM 20 − RM 16 = RM 4.</li><li>Bahagian kenaikan daripada harga asal = 4 ÷ 16 = 0.25.</li><li>Peratus kenaikan = 0.25 × 100% = 25%.</li><li>Jawapan: <b>D</b> (25%).</li></ol><h5>🔍 Semak jawapan</h5><p>Sebagai semakan, 25% daripada RM 16 ialah RM 4; RM 16 + RM 4 = RM 20.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (0.25%): 0.25% tersilap menganggap perpuluhan 0.25 terus sebagai peratus.</li><li><b>B</b> (4%): 4% menyalin kenaikan RM 4 sebagai peratus tanpa membahagi harga asal.</li><li><b>C</b> (20%): 20% menggunakan RM 20 sebagai penyebut: 4 ÷ 20 = 0.20, sedangkan itu harga baharu.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tandakan perkataan asal; asas peratus kenaikan sentiasa nilai asal.</p>",
"<h5>🧭 Faham soalan</h5><p>Sebanyak 300 g tepung menghasilkan 12 kek cawan. Aisyah mempunyai 1 kg tepung dan bahan lain mencukupi.</p><h5>💡 Strategi</h5><p>Tukar kilogram kepada gram dahulu, kemudian cari tepung bagi sebiji kek. Bahagi jumlah tepung dengan keperluan setiap biji.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>1 kg = 1 000 g.</li><li>Tepung untuk sebiji kek cawan = 300 g ÷ 12 = 25 g.</li><li>Bilangan kek cawan = 1 000 g ÷ 25 g = 40.</li><li>Jawapan: <b>40 biji</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>40 × 25 g = 1 000 g, tepat sama dengan tepung yang ada. Jadi 40 ialah bilangan maksimum.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Jangan membahagi 1 kg terus dengan 25 g; tukarkan kedua-duanya kepada unit yang sama.</li><li>Jangan membundarkan bilangan kek ke atas jika tepung tidak mencukupi bagi kek terakhir.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam soalan kadar, cari kuantiti bagi satu unit dahulu; unit yang sama akan saling hapus semasa membahagi.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah piktograf menggunakan satu bulatan penuh bagi 8 murid dan separuh bulatan bagi 4 murid. Beza hari paling ramai dan paling sedikit diminta.</p><h5>💡 Strategi</h5><p>Baca petunjuk rajah, kira jumlah setiap hari yang relevan, kemudian tolak nilai terkecil daripada terbesar.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Khamis mempunyai 5 bulatan penuh: 5 × 8 = 40 murid. Ini paling ramai.</li><li>Jumaat mempunyai 1 bulatan penuh dan 1 separuh bulatan: 8 + 4 = 12 murid. Ini paling sedikit.</li><li>Beza = 40 − 12 = 28 murid.</li><li>Jawapan: <b>B</b> (28 murid).</li></ol><h5>🔍 Semak jawapan</h5><p>Nilai hari lain ialah Isnin 24, Selasa 36 dan Rabu 16 murid; semuanya di antara 12 dengan 40.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (24): 24 boleh muncul jika separuh bulatan tersalah dianggap bulatan penuh, lalu Jumaat dikira 16.</li><li><b>C</b> (32): 32 terhasil jika separuh bulatan Jumaat diabaikan dan Jumaat dikira 8.</li><li><b>D</b> (36): 36 ialah bilangan murid pada Selasa, bukannya beza terbesar dengan terkecil.</li></ul><h5>📌 Tip peperiksaan</h5><p>Baca nilai simbol separuh sebelum membandingkan lajur piktograf.</p>",
"<h5>🧭 Faham soalan</h5><p>Harga beg di Hatyai ialah 1 350 baht. Di Malaysia harganya RM 189. Kadar tukaran ialah RM 1 bagi 7.50 baht.</p><h5>💡 Strategi</h5><p>Tukar kedua-dua harga kepada ringgit dahulu. Untuk menukar baht kepada ringgit, bahagi dengan 7.50 baht bagi setiap RM 1.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Harga di Hatyai = 1 350 baht ÷ 7.50 baht bagi RM 1 = RM 180.</li><li>Bandingkan: RM 180 lebih rendah daripada RM 189.</li><li>Beza harga = RM 189 − RM 180 = RM 9.</li><li>Jawapan: <b>A</b> (di Hatyai, lebih murah RM 9.00).</li></ol><h5>🔍 Semak jawapan</h5><p>RM 189 × 7.50 = 1 417.50 baht; bezanya dengan 1 350 baht ialah 67.50 baht = RM 9.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Di Hatyai, lebih murah RM 67.50): RM 67.50 tersalah melabel beza 67.50 baht sebagai ringgit.</li><li><b>C</b> (Di Malaysia, lebih murah RM 1 161.00): RM 1 161.00 datang daripada 1 350 − 189, iaitu menolak nilai berlainan mata wang.</li><li><b>D</b> (Di Malaysia, lebih murah RM 9 936.00): RM 9 936.00 timbul jika 1 350 didarab 7.50 lalu dibandingkan dengan RM 189.</li></ul><h5>📌 Tip peperiksaan</h5><p>Semak unit sebelum menolak harga dalam dua mata wang berbeza.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual memberi lapan masa larian dalam saat. Kita perlu kenal pasti mod dan julat masa.</p><h5>💡 Strategi</h5><p>Mod ialah nilai paling kerap muncul; mungkin lebih daripada satu. Julat ialah nilai maksimum tolak nilai minimum.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada jadual, 12.8 s muncul dua kali dan 13.2 s juga muncul dua kali; masa lain masing-masing sekali.</li><li>Oleh itu, kedua-dua 12.8 s dan 13.2 s ialah mod.</li><li>Masa terbesar ialah 15.0 s dan terkecil 12.8 s; julat = 15.0 − 12.8 = 2.2 s.</li><li>Jawapan: <b>A</b> (mod 12.8 s dan 13.2 s; julat 2.2 s).</li></ol><h5>🔍 Semak jawapan</h5><p>Susun masa: 12.8, 12.8, 13.2, 13.2, 13.5, 14.1, 14.6, 15.0 s. Dua nilai terawal masing-masing berulang dua kali.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Mod: 12.8 s sahaja; julat: 2.2 s): 12.8 s bukan satu-satunya mod kerana 13.2 s juga muncul dua kali.</li><li><b>C</b> (Mod: 12.8 s dan 13.2 s; julat: 1.4 s): Julat 1.4 s datang daripada 14.6 − 13.2; kedua-duanya bukan nilai ekstrem.</li><li><b>D</b> (Tiada mod; julat: 2.2 s): Ada mod kerana dua nilai berkongsi kekerapan tertinggi.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi julat, cari nilai ekstrem dalam seluruh jadual, bukan hanya hujung baris.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan dua garis selari dipotong satu garis. Sudut pedalaman pada sebelah yang sama berlabel (3x + 10)° dan (2x + 20)°.</p><h5>💡 Strategi</h5><p>Dua sudut pedalaman sepihak bagi garis selari berjumlah 180°. Bentuk persamaan dan selesaikan x.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada rajah, (3x + 10)° + (2x + 20)° = 180°.</li><li>Gabung sebutan sejenis: 5x + 30 = 180.</li><li>Tolak 30 pada kedua-dua belah: 5x = 150. Bahagi 5: x = 30.</li><li>Jawapan: <b>B</b> (30).</li></ol><h5>🔍 Semak jawapan</h5><p>Apabila x = 30, sudut atas = 3 × 30 + 10 = 100° dan sudut bawah = 2 × 30 + 20 = 80°. Jumlahnya 180°.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (10): 10 terhasil jika kedua-dua sudut disamakan, seperti sudut selang-seli; kedudukannya tidak begitu.</li><li><b>C</b> (36): 36 diperoleh daripada 180 ÷ 5 dengan mengabaikan pemalar 10 dan 20.</li><li><b>D</b> (66): 66 diperoleh jika jumlah sudut tersalah dianggap 360°: (360 − 30) ÷ 5 = 66.</li></ul><h5>📌 Tip peperiksaan</h5><p>Kenal pasti kedudukan sudut dalam rajah sebelum memilih peraturan garis selari.</p>",
"<h5>🧭 Faham soalan</h5><p>Tanah berbentuk L mempunyai sisi bawah 14 m, kiri 10 m, lekuk mendatar 6 m dan lekuk tegak 4 m. Kos pagar RM 12.50 semeter.</p><h5>💡 Strategi</h5><p>Pagar mengikuti keliling, jadi cari sisi yang hilang dan jumlah panjang sempadan. Darab perimeter dengan kos semeter.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Sisi mendatar atas = 14 − 6 = 8 m. Sisi tegak kanan = 10 − 4 = 6 m.</li><li>Perimeter = 14 + 6 + 6 + 4 + 8 + 10 = 48 m.</li><li>Kos = 48 × RM 12.50 = RM 600.</li><li>Jawapan: <b>C</b> (RM 600).</li></ol><h5>🔍 Semak jawapan</h5><p>Jumlah sisi mendatar = 14 + 6 + 8 = 28 m; jumlah sisi tegak = 10 + 4 + 6 = 20 m. Keseluruhan 48 m.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 425): RM 425 ialah 34 × RM 12.50; 34 m hanya jumlah sisi berlabel, belum lengkap.</li><li><b>B</b> (RM 550): RM 550 ialah 44 × RM 12.50; satu sisi 4 m tertinggal.</li><li><b>D</b> (RM 1 450): RM 1 450 menggunakan luas 116 m² × RM 12.50, sedangkan kos diberi bagi setiap meter pagar.</li></ul><h5>📌 Tip peperiksaan</h5><p>Perkataan sekeliling dan semeter menandakan perimeter, bukannya luas.</p>",
"<h5>🧭 Faham soalan</h5><p>Enam orang duduk pada enam kerusi sama jarak di meja bulat. Beberapa pasangan bertentangan dan bersebelahan diberikan; kita cari orang di hadapan T.</p><h5>💡 Strategi</h5><p>Nomborkan kerusi mengikut bulatan. Kerusi yang beza kedudukannya tiga adalah bertentangan. Uji kedua-dua tempat R yang mungkin.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Letakkan P di kerusi 1 dan Q di kerusi 4 kerana mereka bertentangan.</li><li>Jika R di kerusi 3, S di kerusi 6. Baki kerusi 2 dan 5. T tidak boleh di kerusi 2 kerana bersebelahan P, jadi T di 5 dan U di 2.</li><li>Jika R di kerusi 5, S di kerusi 2. Baki kerusi 3 dan 6. T tidak boleh di 6 kerana bersebelahan P, jadi T di 3 dan U di 6.</li><li>Dalam kedua-dua susunan, T bertentangan U. Jawapan: <b>D</b> (U).</li></ol><h5>🔍 Semak jawapan</h5><p>Kes pertama: kerusi 5 dan 2 berbeza tiga tempat. Kes kedua: kerusi 3 dan 6 juga berbeza tiga tempat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (P): P bertentangan Q mengikut syarat awal, maka tidak boleh bertentangan T.</li><li><b>B</b> (R): R sentiasa bersebelahan Q, sedangkan kerusi yang bertentangan T diisi U.</li><li><b>C</b> (S): S bertentangan R, bukan T, dalam kedua-dua kes.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk meja bulat, tetapkan satu orang di kerusi 1; putaran susunan tidak menghasilkan kes baharu.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah 1 menggunakan 9 jubin, Rajah 2 menggunakan 14 dan Rajah 3 menggunakan 19. Rajah 40 ditanya.</p><h5>💡 Strategi</h5><p>Pola ini jujukan aritmetik dengan beza tetap 5. Sebutan ke-n diperoleh daripada sebutan pertama ditambah (n − 1) beza.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Beza 14 − 9 = 5; beza 19 − 14 = 5.</li><li>Rajah 40 berada 40 − 1 = 39 langkah selepas Rajah 1.</li><li>Bilangan jubin = 9 + 39 × 5 = 9 + 195 = 204.</li><li>Jawapan: <b>B</b> (204 jubin).</li></ol><h5>🔍 Semak jawapan</h5><p>Rumus 5n + 4 memberi 5 × 1 + 4 = 9, 5 × 2 + 4 = 14, dan 5 × 40 + 4 = 204.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (200): 200 ialah 5 × 40; ia mengabaikan tambahan tetap 4 jubin.</li><li><b>C</b> (209): 209 ialah 9 + 40 × 5; ini menggunakan 40 langkah, sedangkan dari Rajah 1 ke Rajah 40 hanya 39 langkah.</li><li><b>D</b> (360): 360 ialah 9 × 40; bilangan jubin tidak berkadar terus dengan nombor rajah.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi jujukan aritmetik, ingat bilangan lonjakan dari sebutan pertama ke ke-n ialah n − 1.</p>",
"<h5>🧭 Faham soalan</h5><p>Tiga pen dan dua buku nota berharga RM 13.00; dua pen dan tiga buku nota RM 14.50. Harga dua pen serta dua buku diminta.</p><h5>💡 Strategi</h5><p>Tambah dua maklumat harga. Ini memberi lima pen dan lima buku, lalu bahagi lima untuk harga sepasang pen dan buku.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlahkan kedua-dua pembelian: 5 pen + 5 buku = RM 13.00 + RM 14.50 = RM 27.50.</li><li>Bahagi lima: 1 pen + 1 buku = RM 27.50 ÷ 5 = RM 5.50.</li><li>Darab dua: 2 pen + 2 buku = 2 × RM 5.50 = RM 11.00.</li><li>Jawapan: <b>A</b> (RM 11.00).</li></ol><h5>🔍 Semak jawapan</h5><p>Semakan: daripada persamaan asal, pen RM 2.00 dan buku RM 3.50. Maka 2 × RM 2.00 + 2 × RM 3.50 = RM 11.00.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (RM 13.75): RM 13.75 ialah purata RM 13.00 dan RM 14.50, bukan harga dua pasang.</li><li><b>C</b> (RM 22.00): RM 22.00 ialah RM 27.50 × 4/5, iaitu harga 4 batang pen dan 4 buah buku nota; soalan meminta 2 batang pen dan 2 buah buku nota sahaja.</li><li><b>D</b> (RM 27.50): RM 27.50 ialah harga lima pen bersama lima buku, bukannya dua setiap satu.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila pekali dua persamaan bertukar tempat, tambah dahulu sebelum menyelesaikan harga satu item.</p>",
"<h5>🧭 Faham soalan</h5><p>Harga selepas diskaun 15% ialah RM 170. Harga asal jam tangan yang belum didiskaun diminta.</p><h5>💡 Strategi</h5><p>Selepas diskaun, pelanggan membayar 100% − 15% = 85% harga asal. Bahagi harga akhir dengan 0.85.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Peratus harga yang dibayar = 100% − 15% = 85% = 0.85.</li><li>Jika harga asal P, maka 0.85P = RM 170.</li><li>P = RM 170 ÷ 0.85 = RM 200.</li><li>Jawapan: <b>D</b> (RM 200.00).</li></ol><h5>🔍 Semak jawapan</h5><p>15% daripada RM 200 = RM 30; RM 200 − RM 30 = RM 170, sepadan dengan harga diberi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 144.50): RM 144.50 ialah RM 170 × 0.85, iaitu memberi diskaun kedua pada harga akhir.</li><li><b>B</b> (RM 185.00): RM 185.00 ialah 170 + 15; peratus 15% bukan nilai RM 15.</li><li><b>C</b> (RM 195.50): RM 195.50 ialah 170 × 1.15; diskaun asal dikira berdasarkan RM 200, bukan RM 170.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk mencari harga asal selepas diskaun, bahagi dengan peratus yang dibayar, bukan tambah peratus pada harga akhir.</p>",
"<h5>🧭 Faham soalan</h5><p>Jarak pergi 200 km pada 100 km/j dan jarak balik 200 km pada 80 km/j. Laju purata seluruh perjalanan diminta.</p><h5>💡 Strategi</h5><p>Laju purata ialah jumlah jarak dibahagi jumlah masa. Dua perjalanan sama jauh mengambil masa berlainan, jadi kira masa secara berasingan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Masa pergi = 200 km ÷ 100 km/j = 2 jam.</li><li>Masa balik = 200 km ÷ 80 km/j = 2.5 jam.</li><li>Jumlah jarak = 200 + 200 = 400 km; jumlah masa = 2 + 2.5 = 4.5 jam.</li><li>Laju purata = 400 ÷ 4.5 = 88.888… km/j ≈ 88.89 km/j. Jawapan: <b>A</b> (88.89 km/j).</li></ol><h5>🔍 Semak jawapan</h5><p>88.89 km/j × 4.5 jam ≈ 400.005 km; beza kecil disebabkan pembundaran dua tempat perpuluhan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (90.00 km/j): 90.00 km/j ialah purata terus (100 + 80) ÷ 2, sedangkan masa pada kedua-dua laju berbeza.</li><li><b>C</b> (100.00 km/j): 100.00 km/j mengabaikan perjalanan balik yang lebih perlahan.</li><li><b>D</b> (180.00 km/j): 180.00 km/j ialah jumlah dua laju, bukan laju purata.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tulis rumus jumlah jarak ÷ jumlah masa sebelum memasukkan nombor bagi perjalanan berperingkat.</p>",
"<h5>🧭 Faham soalan</h5><p>Ada 4 guli merah, 6 biru dan sebilangan hijau. Kebarangkalian biru 1/3; kebarangkalian hijau diminta.</p><h5>💡 Strategi</h5><p>Gunakan bilangan biru dan peluangnya untuk mencari jumlah guli. Kemudian tolak warna yang diketahui dan bentuk pecahan peluang hijau.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>6 ÷ jumlah guli = 1/3, maka jumlah guli = 6 × 3 = 18.</li><li>Bilangan hijau = 18 − 4 − 6 = 8.</li><li>Peluang hijau = 8 ÷ 18 = 8/18 = 4/9.</li><li>Jawapan: <b>C</b> (4/9).</li></ol><h5>🔍 Semak jawapan</h5><p>Jumlah peluang merah, biru dan hijau ialah 4/18 + 6/18 + 8/18 = 18/18 = 1.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (2/9): 2/9 ialah 4/18, iaitu kebarangkalian guli merah.</li><li><b>B</b> (1/3): 1/3 ialah kebarangkalian guli biru yang sudah diberi; bilangan hijau bukan 6.</li><li><b>D</b> (2/3): 2/3 ialah peluang bukan biru, yang merangkumi merah dan hijau bersama.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam kebarangkalian pilihan rawak, penyebut ialah jumlah semua objek, bukan jumlah warna.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan PQ selari RS. Sudut garis XA dengan PQ ialah 38°, manakala sudut XB dengan RS ialah 47°. Sudut AXB ialah x.</p><h5>💡 Strategi</h5><p>Lukis garis bantu melalui X yang selari dengan PQ dan RS. Sudut selang-seli memindahkan kedua-dua sudut ke titik X.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Pada bahagian atas garis bantu melalui X, sudut antara XA dan garis itu ialah 38°.</li><li>Pada bahagian bawahnya, sudut antara garis itu dan XB ialah 47°.</li><li>Sudut AXB ialah jumlah kedua-dua bahagian: x = 38° + 47° = 85°.</li><li>Jawapan: <b>A</b> (85°).</li></ol><h5>🔍 Semak jawapan</h5><p>Semak songsang: 85° − 38° = 47°, sepadan dengan sudut kedua yang diberi. Garis bantu melalui X membahagi sudut AXB kepada 38° dan 47°.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (95°): 95° diperoleh daripada 180° − 38° − 47° = 95°, iaitu sudut ketiga jika 38° dan 47° dianggap dua sudut dalam sebuah segi tiga; rajah ini bukan segi tiga itu dan sudut di X ialah jumlah dua sudut selang-seli.</li><li><b>C</b> (133°): 133° ialah 180° − 47°, hanya menggunakan satu sudut diberi.</li><li><b>D</b> (142°): 142° ialah 180° − 38°, juga hanya menggunakan satu sudut diberi.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk bentuk zigzag antara garis selari, lukis garis selari tambahan melalui bucu tengah.</p>",
"<h5>🧭 Faham soalan</h5><p>Laci mengandungi 10 stoking hitam, 8 putih dan 6 kelabu. Kita mahu menjamin sekurang-kurangnya dua stoking putih dalam gelap.</p><h5>💡 Strategi</h5><p>Fikirkan keadaan paling malang: semua stoking bukan putih mungkin terambil dahulu. Selepas itu, ambil dua lagi untuk menjamin dua putih.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bilangan stoking bukan putih = 10 hitam + 6 kelabu = 16.</li><li>Dalam keadaan paling malang, 16 cabutan pertama semuanya bukan putih.</li><li>Cabutan ke-17 memberi putih pertama; cabutan ke-18 memberi putih kedua. Minimum = 16 + 2 = 18.</li><li>Jawapan: <b>D</b> (18 stoking).</li></ol><h5>🔍 Semak jawapan</h5><p>Dengan 17 cabutan masih mungkin ada 10 hitam, 6 kelabu dan hanya 1 putih. Dengan 18 cabutan, dua putih tidak dapat dielakkan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (4): 4 mungkin menjamin dua stoking sewarna, tetapi tidak semestinya putih.</li><li><b>B</b> (16): 16 cabutan boleh terdiri seluruhnya daripada stoking bukan putih.</li><li><b>C</b> (17): 17 cabutan hanya menjamin sekurang-kurangnya satu stoking putih.</li></ul><h5>📌 Tip peperiksaan</h5><p>Perkataan memastikan menuntut kiraan kes paling malang, bukan kebarangkalian purata.</p>",
"<h5>🧭 Faham soalan</h5><p>Jujukan mempunyai dua pola berselang-seli: kedudukan ganjil naik dan kedudukan genap turun. Sebutan ke-40 diminta.</p><h5>💡 Strategi</h5><p>Pisahkan sebutan ganjil dan genap. Oleh sebab 40 genap, cari sebutan ke-20 dalam jujukan genap.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Sebutan genap ialah 100, 96, 92, 88, …; bezanya 96 − 100 = −4.</li><li>Kedudukan ke-40 ialah kedudukan ke-40 ÷ 2 = ke-20 dalam pola genap.</li><li>Dari sebutan genap pertama ke ke-20 ada 20 − 1 = 19 penurunan. Nilainya 100 − 19 × 4 = 100 − 76 = 24.</li><li>Jawapan: <b>24</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Sebutan genap ke-1 ialah 100, ke-2 ialah 96, dan rumus 100 − 4(n − 1) menghasilkan 24 apabila n = 20.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Jangan gunakan 40 sebagai indeks dalam pola genap; hanya 20 sebutan genap muncul dalam 40 kedudukan.</li><li>Jangan ikut pola ganjil 3, 7, 11, …; kedudukan ke-40 ialah genap.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi dua jujukan selang-seli, bahagikan nombor kedudukan genap dengan 2 dahulu.</p>",
"<h5>🧭 Faham soalan</h5><p>Gaji RM 3 200 digunakan berturutan untuk sewa 35%, makanan suku daripada baki, dan simpanan 40% daripada baki akhir.</p><h5>💡 Strategi</h5><p>Kira baki selepas setiap perbelanjaan. Setiap pecahan atau peratus merujuk kepada jumlah pada tahap yang disebut, bukan selalu gaji asal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Sewa = 35% × RM 3 200 = 0.35 × RM 3 200 = RM 1 120. Baki = RM 3 200 − RM 1 120 = RM 2 080.</li><li>Makanan = 1/4 × RM 2 080 = RM 520. Baki selepas makanan = RM 2 080 − RM 520 = RM 1 560.</li><li>Simpanan = 40% × RM 1 560 = 0.40 × RM 1 560 = RM 624.</li><li>Jawapan: <b>B</b> (RM 624.00).</li></ol><h5>🔍 Semak jawapan</h5><p>Simpanan RM 624 lebih kecil daripada baki RM 1 560. Nisbahnya 624 ÷ 1 560 = 0.40 = 40%.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 520.00): RM 520.00 ialah belanja makanan, bukan wang yang disimpan.</li><li><b>C</b> (RM 832.00): RM 832.00 ialah 40% daripada RM 2 080; makanan belum ditolak.</li><li><b>D</b> (RM 1 280.00): RM 1 280.00 ialah 40% daripada gaji asal RM 3 200, sedangkan simpanan dikira selepas dua belanja.</li></ul><h5>📌 Tip peperiksaan</h5><p>Gariskan perkataan baki itu dan selepas itu untuk menentukan asas setiap peratus.</p>",
"<h5>🧭 Faham soalan</h5><p>Lima nombor bulat positif mempunyai min 6.2, median 7 dan satu-satunya mod 8. Julat terbesar diminta.</p><h5>💡 Strategi</h5><p>Cari jumlah melalui min, susun nombor menaik dan hadkan dua nombor kecil. Untuk membesarkan julat, kecilkan nombor pertama tanpa menghasilkan mod kedua.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah lima nombor = 5 × 6.2 = 31. Median ialah nombor ketiga, iaitu 7.</li><li>Oleh sebab 8 satu-satunya mod, dua nombor akhir ialah 8 dan 8. Susunan ialah a, b, 7, 8, 8 dengan a &lt; b &lt; 7.</li><li>Maka a + b = 31 − 7 − 8 − 8 = 8. Pasangan positif berbeza yang memenuhi a &lt; b &lt; 7 ialah (2, 6) dan (3, 5).</li><li>Pilih a terkecil, iaitu 2. Julat = 8 − 2 = 6. Jawapan: <b>C</b> (6).</li></ol><h5>🔍 Semak jawapan</h5><p>Set 2, 6, 7, 8, 8 berjumlah 31, mediannya 7 dan hanya 8 berulang. Semua syarat dipenuhi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (4): 4 boleh muncul daripada 4, 4, 7, 8, 8, tetapi 4 juga mod, menyalahi syarat mod tunggal.</li><li><b>B</b> (5): 5 diperoleh daripada set 3, 5, 7, 8, 8; set ini sah tetapi julatnya bukan yang terbesar.</li><li><b>D</b> (7): 7 memerlukan minimum 1; set 1, 7, 7, 8, 8 mempunyai dua mod, 7 dan 8.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk maksimum atau minimum yang terikat syarat, bina set yang memenuhi semua syarat dan semak kes ekstrem.</p>",
"<h5>🧭 Faham soalan</h5><p>Seorang daripada empat murid mengambil kek dan tepat dua pernyataan benar. Arif berkata Chong benar; Chong berkata Devi mengambilnya.</p><h5>💡 Strategi</h5><p>Pernyataan Arif mempunyai nilai benar yang sama dengan pernyataan Chong. Uji setiap calon pengambil dan hitung bilangan pernyataan benar.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jika Arif mengambil kek: Arif salah, Bella benar, Chong salah, Devi benar. Tepat dua benar; kes ini sesuai.</li><li>Jika Bella mengambilnya: Arif salah, Bella salah, Chong salah, Devi benar. Hanya satu benar.</li><li>Jika Chong mengambilnya: Arif salah, Bella benar, Chong salah, Devi salah. Hanya satu benar.</li><li>Jika Devi mengambilnya: Arif benar, Bella benar, Chong benar, Devi benar. Empat benar.</li><li>Hanya kes pertama memenuhi syarat. Jawapan: <b>A</b> (Arif).</li></ol><h5>🔍 Semak jawapan</h5><p>Apabila Arif pengambilnya, dua yang benar tepat Bella dan Devi. Ini juga selaras dengan syarat seorang sahaja mengambil kek.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Bella): Jika Bella pengambilnya, hanya Devi bercakap benar, bukan dua orang.</li><li><b>C</b> (Chong): Jika Chong pengambilnya, hanya Bella bercakap benar.</li><li><b>D</b> (Devi): Jika Devi pengambilnya, keempat-empat pernyataan benar.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bina empat baris kes calon dan kira bilangan pernyataan benar; jangan meneka daripada satu kenyataan sahaja.</p>",
"<h5>🧭 Faham soalan</h5><p>Nombor 1 ditulis sekali, 2 dua kali, dan seterusnya. Kita cari nombor yang menduduki tempat ke-100.</p><h5>💡 Strategi</h5><p>Kira kedudukan akhir setiap kumpulan menggunakan jumlah 1 + 2 + … + n = n(n + 1) ÷ 2. Cari kumpulan yang meliputi tempat ke-100.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kedudukan akhir kumpulan 13 ialah 13 × 14 ÷ 2 = 91.</li><li>Kedudukan akhir kumpulan 14 ialah 14 × 15 ÷ 2 = 105.</li><li>Jadi tempat 92 hingga 105 semuanya bernilai 14. Tempat ke-100 terletak di antara 92 dan 105.</li><li>Jawapan: <b>14</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Kumpulan 14 mempunyai 105 − 91 = 14 sebutan, tepat seperti peraturan nombor 14 ditulis 14 kali.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Jangan pilih 13 hanya kerana 91 hampir kepada 100; tempat selepas 91 sudah memasuki kumpulan 14.</li><li>Jangan pilih 100 sebagai nilai sebutan; 100 ialah kedudukan, bukan nombor yang ditulis.</li></ul><h5>📌 Tip peperiksaan</h5><p>Cari dua jumlah berturutan yang mengapit kedudukan sasaran.</p>",
"<h5>🧭 Faham soalan</h5><p>Pelan A mengenakan RM 30 serta RM 0.10 seminit; pelan B RM 12 serta RM 0.25 seminit. Kita cari minit bulat terkecil apabila A benar-benar lebih murah.</p><h5>💡 Strategi</h5><p>Bina ketaksamaan kos A kurang daripada kos B. Titik kos sama ialah sempadan, jadi masa yang diminta mesti melebihinya.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bagi m minit, kos A = 30 + 0.10m dan kos B = 12 + 0.25m, kedua-duanya dalam RM.</li><li>Syarat A lebih murah: 30 + 0.10m &lt; 12 + 0.25m.</li><li>Tolak 12 dan 0.10m: 18 &lt; 0.15m. Bahagi 0.15: 120 &lt; m.</li><li>Nombor bulat terkecil melebihi 120 ialah 121. Jawapan: <b>C</b> (121 minit).</li></ol><h5>🔍 Semak jawapan</h5><p>Pada 120 minit kedua-duanya RM 42. Pada 121 minit, A = RM 42.10 dan B = RM 42.25; A lebih murah RM 0.15.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (72): 72 datang daripada 18 ÷ 0.25, tetapi beza kadar seminit ialah RM 0.15.</li><li><b>B</b> (120): 120 ialah titik kedua-dua pelan sama mahal, bukan A lebih murah.</li><li><b>D</b> (180): 180 datang daripada 18 ÷ 0.10, iaitu menggunakan kadar pelan A sahaja; beza kadar seminit ialah RM 0.25 − RM 0.10 = RM 0.15, jadi 180 bukan nilai terkecil.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bezakan simbol kurang daripada dengan kurang atau sama; titik seri tidak memenuhi perkataan lebih murah.</p>",
"<h5>🧭 Faham soalan</h5><p>Harga makanan RM 80 ditolak baucar RM 10 dahulu. Kemudian caj perkhidmatan 10% dan cukai 6% dikenakan mengikut urutan.</p><h5>💡 Strategi</h5><p>Ikut urutan yang diberi. Tolak baucar dahulu, darab 1.10 untuk caj perkhidmatan dan darab 1.06 untuk cukai atas jumlah baharu.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Harga selepas baucar = RM 80 − RM 10 = RM 70.</li><li>Caj perkhidmatan = 10% × RM 70 = RM 7; jumlah selepas caj = RM 70 + RM 7 = RM 77.</li><li>Cukai = 6% × RM 77 = RM 4.62; jumlah akhir = RM 77 + RM 4.62 = RM 81.62.</li><li>Jawapan: <b>B</b> (RM 81.62).</li></ol><h5>🔍 Semak jawapan</h5><p>Kiraan ringkas RM 70 × 1.10 × 1.06 = RM 81.62, sama dengan kiraan berperingkat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 81.20): RM 81.20 ialah 70 × 1.16; ini mengira cukai dan caj serentak pada RM 70.</li><li><b>C</b> (RM 82.80): RM 82.80 ialah 80 × 1.16 − 10; kedua-dua peratus dikira pada harga sebelum baucar.</li><li><b>D</b> (RM 83.28): RM 83.28 ialah 80 × 1.10 × 1.06 − 10; baucar ditolak terlalu lewat.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi caj berturutan, darab faktor satu demi satu dan perhatikan bila baucar ditolak.</p>",
"<h5>🧭 Faham soalan</h5><p>Dua bandar berjarak 310 km. Kereta A bermula 8:00 pagi pada 80 km/j; B bermula 8:30 pagi dari arah bertentangan pada 100 km/j.</p><h5>💡 Strategi</h5><p>Kira dahulu jarak yang A tempuh dalam setengah jam awal. Selepas B bertolak, kedua-duanya mendekat dengan jumlah laju.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Dari 8:00 ke 8:30 ialah 30 minit = 0.5 jam. A menempuh 80 × 0.5 = 40 km.</li><li>Jarak antara kereta pada 8:30 ialah 310 − 40 = 270 km.</li><li>Laju mendekat = 80 + 100 = 180 km/j. Masa hingga bertemu = 270 ÷ 180 = 1.5 jam = 1 jam 30 minit.</li><li>8:30 pagi + 1 jam 30 minit = 10:00 pagi. Jawapan: <b>B</b> (10:00 pagi).</li></ol><h5>🔍 Semak jawapan</h5><p>Pada 10:00, A menempuh 2 jam × 80 = 160 km; B menempuh 1.5 jam × 100 = 150 km. Jumlah 310 km.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (9:43 pagi): 9:43 pagi terhasil jika kedua-dua kereta dianggap bermula pada 8:00.</li><li><b>C</b> (10:13 pagi): 10:13 pagi terhasil jika 310 km penuh digunakan selepas 8:30, mengabaikan 40 km A sudah bergerak.</li><li><b>D</b> (10:30 pagi): 10:30 pagi terlalu lewat; pada waktu itu jumlah jarak kedua-dua kereta sudah melebihi 310 km.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam masalah mula berlainan waktu, gerakkan jam ke waktu kedua-duanya sudah bergerak sebelum guna laju relatif.</p>",
"<h5>🧭 Faham soalan</h5><p>Enam nombor telah disusun menaik: 4, 7, 10, x, 22, 27. Median 12 dan min diminta.</p><h5>💡 Strategi</h5><p>Bagi enam data, median ialah purata nombor ketiga dan keempat. Cari x, kemudian bahagi jumlah semua data dengan enam.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>(10 + x) ÷ 2 = 12, maka 10 + x = 24 dan x = 24 − 10 = 14.</li><li>Jumlah data = 4 + 7 + 10 + 14 + 22 + 27 = 84.</li><li>Min = jumlah ÷ bilangan data = 84 ÷ 6 = 14.</li><li>Jawapan: <b>C</b> (14.00).</li></ol><h5>🔍 Semak jawapan</h5><p>Susunan kekal menaik kerana 10 &lt; 14 &lt; 22. Median = (10 + 14) ÷ 2 = 12 seperti diberi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (12.00): 12.00 ialah median yang diberi, bukan min enam nombor.</li><li><b>B</b> (13.67): 13.67 terhasil jika x disamakan dengan median 12, lalu jumlah 82 dibahagi 6.</li><li><b>D</b> (15.50): 15.50 ialah (4 + 27) ÷ 2, titik tengah nilai terkecil dan terbesar, bukan min.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bezakan median daripada min: median bergantung kedudukan, min menggunakan semua nilai.</p>",
"<h5>🧭 Faham soalan</h5><p>Mata pemerhati 1.5 m di atas tanah dan jarak mendatar ke menara 40 m. Sudut dongakan ke puncak ialah 35°.</p><h5>💡 Strategi</h5><p>Dalam segi tiga bersudut tegak pada aras mata, tangen sudut ialah tinggi di atas mata dibahagi jarak mendatar. Tambah tinggi mata selepas itu.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada rajah, sisi bersebelahan sudut ialah 40 m; sisi bertentangan ialah tinggi menara di atas aras mata, h.</li><li>tan 35° = h ÷ 40, maka h = 40 × tan 35° = 40 × 0.7002075… = 28.0083… m.</li><li>Tinggi menara dari tanah = 28.0083… + 1.5 = 29.5083… m. Bundar kepada dua tempat perpuluhan: 29.51 m.</li><li>Jawapan: <b>D</b> (29.51 m).</li></ol><h5>🔍 Semak jawapan</h5><p>(29.5083… − 1.5) ÷ 40 ≈ 0.7002075, iaitu tan 35°. Unit akhir ialah meter.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (22.94 m): 22.94 m datang daripada 40 × sin 35° tanpa menambah tinggi mata; 40 m ialah sisi bersebelahan, bukan hipotenus.</li><li><b>B</b> (24.44 m): 24.44 m menambah 1.5 m kepada 40 × sin 35°; fungsi trigonometri masih salah.</li><li><b>C</b> (28.01 m): 28.01 m ialah tinggi di atas aras mata sahaja; 1.5 m belum ditambah.</li></ul><h5>📌 Tip peperiksaan</h5><p>Lakar garis mengufuk dari mata dan label sisi bertentangan serta bersebelahan sebelum memilih tan.</p>",
"<h5>🧭 Faham soalan</h5><p>Dua peristiwa umur diberi: dahulu ibu sebaya umur anak sekarang ketika anak 4 tahun; kelak anak sebaya umur ibu sekarang ketika ibu 82 tahun.</p><h5>💡 Strategi</h5><p>Beza umur ibu dan anak sentiasa tetap. Gunakan beza itu untuk bergerak jumlah tahun yang sama ke masa dahulu dan masa depan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Katakan umur anak sekarang A dan beza umur d. Umur ibu sekarang A + d.</li><li>d tahun dahulu ibu berumur A dan anak berumur A − d = 4. Jadi A = d + 4.</li><li>d tahun lagi anak berumur A + d, sama dengan umur ibu sekarang. Ibu ketika itu berumur A + 2d = 82.</li><li>Gantikan A = d + 4: d + 4 + 2d = 82; 3d = 78; d = 26. Maka A = 26 + 4 = 30.</li><li>Umur ibu sekarang = A + d = 30 + 26 = 56 tahun. Jawapan: <b>D</b> (56 tahun).</li></ol><h5>🔍 Semak jawapan</h5><p>26 tahun dahulu ibu 30 dan anak 4. Dalam 26 tahun lagi anak 56 dan ibu 82. Kedua-dua kenyataan tepat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (26 tahun): 26 tahun ialah beza umur mereka, bukan umur ibu.</li><li><b>B</b> (30 tahun): 30 tahun ialah umur Arjun sekarang.</li><li><b>C</b> (43 tahun): 43 tahun ialah (82 + 4) ÷ 2; purata dua umur pada masa berlainan tidak memberi umur ibu sekarang.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam soalan umur, beza umur kekal sama walaupun masa berubah.</p>",
"<h5>🧭 Faham soalan</h5><p>Larutan awal 400 g mengandungi 15% garam. Tambah 20 g garam, kemudian air tersejat hingga kepekatan 25%. Jisim air tersejat diminta.</p><h5>💡 Strategi</h5><p>Jisim garam kekal semasa air menyejat. Kira garam selepas tambahan, gunakan peratus akhir untuk mencari jisim larutan akhir, kemudian bandingkan jisim larutan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Garam awal = 15% × 400 g = 0.15 × 400 = 60 g. Selepas ditambah, garam = 60 + 20 = 80 g.</li><li>Jisim larutan sebelum pemanasan = 400 + 20 = 420 g.</li><li>Jika 80 g ialah 25% larutan akhir, jisim larutan akhir = 80 ÷ 0.25 = 320 g.</li><li>Air tersejat = 420 − 320 = 100 g. Jawapan: <b>B</b> (100 g).</li></ol><h5>🔍 Semak jawapan</h5><p>Air awal = 400 − 60 = 340 g. Air akhir = 320 − 80 = 240 g. Bezanya 340 − 240 = 100 g.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (80 g): 80 g datang daripada 400 − 320; ini lupa jisim 20 g garam tambahan.</li><li><b>C</b> (180 g): 180 g datang daripada menggunakan 60 g garam asal untuk jisim larutan akhir, walaupun 20 g ditambah.</li><li><b>D</b> (320 g): 320 g ialah jisim seluruh larutan akhir, bukan air yang tersejat.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi penyejatan air, garam kekal; beza jisim sebelum dan selepas pemanasan ialah air yang hilang.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan DE selari BC, AD 6 cm, DB 4 cm dan luas segi tiga ADE 27 cm². Luas trapezium DBCE diminta.</p><h5>💡 Strategi</h5><p>Segi tiga ADE dan ABC serupa kerana DE selari BC. Nisbah luas ialah kuasa dua nisbah sisi sepadan; tolak luas segi tiga kecil daripada besar.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Panjang AB = AD + DB = 6 + 4 = 10 cm. Nisbah sisi AD : AB = 6 : 10 = 3 : 5.</li><li>Nisbah luas ADE : ABC = 3² : 5² = 9 : 25.</li><li>Luas ABC = 27 × 25 ÷ 9 = 75 cm².</li><li>Luas trapezium DBCE = 75 − 27 = 48 cm². Jawapan: <b>C</b> (48 cm²).</li></ol><h5>🔍 Semak jawapan</h5><p>Semakan: luas trapezium dan segi tiga kecil berjumlah 48 + 27 = 75 cm², sama dengan luas segi tiga besar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (18 cm²): 18 cm² terhasil jika luas besar salah dikira 27 × 5 ÷ 3 = 45 cm², lalu 45 − 27.</li><li><b>B</b> (45 cm²): 45 cm² ialah luas segi tiga ABC jika nisbah sisi digunakan terus, 27 × 5 ÷ 3 = 45 cm², tanpa kuasa dua dan tanpa menolak luas ADE; nilai itu bukan luas trapezium.</li><li><b>D</b> (75 cm²): 75 cm² ialah luas keseluruhan segi tiga ABC, belum menolak bahagian ADE.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila bentuk serupa mempunyai nisbah sisi a : b, nisbah luasnya a² : b².</p>"],
"sains":["<h5>🧠 Konsep utama</h5><p>Mitokondria merupakan organel sel berbentuk rod atau sfera yang dikenali sebagai pusat penjanaan tenaga bagi sel. Organel ini bertindak sebagai tapak berlakunya respirasi sel, iaitu proses biokimia yang mengoksidakan glukosa dengan kehadiran oksigen untuk membebaskan tenaga biologi dalam bentuk molekul ATP. Sel-sel tisu yang aktif menjalankan aktiviti metabolisme memerlukan tenaga yang sangat banyak. Otot kardium pada jantung berdegup dan mengecut secara berterusan tanpa henti sepanjang hayat seseorang, maka sel otot jantung mengandungi kepadatan mitokondria yang amat tinggi bagi membekalkan tenaga yang diperlukan.</p><h5>✅ Mengapa jawapan B betul</h5><p>Bilangan mitokondria yang sangat banyak membolehkan sel otot jantung menjalankan respirasi sel dengan giat bagi membebaskan tenaga berterusan untuk pengecutan dan pengenduran otot jantung tanpa mengalami kelesuan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Fungsi menyimpan air, sap sel, gula dan garam mineral dilakukan oleh organel vakuol, bukannya mitokondria.</li><li><b>C</b> — Pengawalan semua aktiviti sel serta penyimpanan maklumat genetik dikendalikan oleh nukleus.</li><li><b>D</b> — Penghasilan makanan melalui proses fotosintesis dilakukan oleh kloroplas yang mengandungi pigmen klorofil di dalam sel tumbuhan.</li></ul><h5>📌 Ingat</h5><p>Kepadatan mitokondria tinggi dalam sel yang sangat aktif: sel otot jantung, sel otot penerbangan burung/serangga, sel sperma dan sel hati.</p>",
"<h5>🧠 Konsep utama</h5><p>Berdasarkan bilangan sel yang membentuk tubuh, hidupan dikelaskan kepada organisma unisel dan organisma multisel. Organisma unisel ialah hidupan ringkas yang hanya terdiri daripada satu sel tunggal. Walaupun hanya satu sel, sel tersebut berupaya menjalankan semua fungsi asas hidupan seperti respirasi, pemakanan, perkumuhan, pembiakan dan pergerakan secara mandiri. Sebaliknya, organisma multisel terdiri daripada lebih daripada satu sel yang tersusun mengikut hierarki sel, tisu, organ dan sistem sel.</p><h5>✅ Mengapa jawapan B betul</h5><p><i>Amoeba</i> ialah protozoa unisel yang hidup di habitat air tawar atau lembap dan tubuhnya dibina daripada satu sel sahaja yang menjalankan semua proses kehidupan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — <i>Hydra</i> ialah haiwan akuatik ringkas multisel daripada filum Cnidaria yang terdiri daripada pelbagai jenis sel khusus.</li><li><b>C</b> — Cendawan ialah kulat makroskopik multisel yang terbentuk daripada jalinan bebenang hifa yang kompleks.</li><li><b>D</b> — <i>Spirogyra</i> merupakan sejenis alga hijau multisel yang membentuk struktur filamen berantai panjang.</li></ul><h5>📌 Ingat</h5><p>Contoh organisma unisel penting: <i>Amoeba</i>, <i>Paramecium</i>, <i>Euglena</i>, <i>Chlamydomonas</i> dan yis. Organisma multisel: <i>Hydra</i>, <i>Spirogyra</i>, <i>Mucor</i>, cendawan dan manusia.</p>",
"<h5>🧠 Konsep utama</h5><p>Sistem pencernaan manusia mencerna makanan daripada molekul kompleks kepada molekul ringkas yang boleh diserap oleh badan. Ileum merupakan bahagian terpanjang dalam usus kecil di mana pencernaan disempurnakan dan penyerapan nutrien berlaku secara intensif. Dinding dalam ileum mempunyai lipatan berlipat-lipat yang dipenuhi dengan unjuran halus seperti jari yang dipanggil vilus dan mikrovilus. Struktur ini menyediakan luas permukaan yang sangat besar untuk menyerap hasil pencernaan seperti glukosa, asid amino, vitamin dan asid lemak ke dalam sistem peredaran darah dan limfa.</p><h5>✅ Mengapa jawapan C betul</h5><p>Pembedahan membuang sebahagian besar ileum mengurangkan luas permukaan penyerapan nutrien secara drastik, mengakibatkan badan tidak dapat menyerap makanan tercerna secukupnya dan membawa kepada penyusutan berat badan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Cecair hempedu dihasilkan oleh organ hati dan disimpan di dalam pundi hempedu, bukan di dalam ileum.</li><li><b>B</b> — Pencernaan protein di dalam perut bergantung kepada enzim pepsin dan asid hidroklorik dalam jus gastrik, tidak terjejas secara langsung oleh pembuangan ileum.</li><li><b>D</b> — Pengunyahan makanan merupakan proses mekanikal yang berlaku di dalam rongga mulut dengan bantuan gigi dan rahang.</li></ul><h5>📌 Ingat</h5><p>Vilus pada dinding ileum berfungsi memaksimumkan penyerapan nutrien. Sebarang kerosakan atau pemotongan ileum akan merencatkan proses penyerapan makanan tercerna.</p>",
"<h5>🧠 Konsep utama</h5><p>Ujian makanan digunakan dalam makmal sains untuk mengenal pasti kelas nutrien utama yang terkandung di dalam sampel makanan. Ujian iodin digunakan khusus untuk mengesan kanji; larutan iodin berwarna perang akan bertukar menjadi biru tua sekiranya kanji hadir. Ujian Benedict digunakan untuk menguji kehadiran gula penurun seperti glukosa; apabila campuran sampel dan larutan Benedict dipanaskan dalam kukus air, larutan biru akan membentuk mendakan merah bata sekiranya terdapat gula penurun. Sekiranya nutrien yang diuji tiada, warna reagen asal tidak berubah.</p><h5>✅ Mengapa jawapan A betul</h5><p>Sampel X memberikan warna biru tua dengan larutan iodin (menunjukkan kehadiran kanji) dan kekal biru dengan larutan Benedict. Sampel Y kekal perang dengan iodin tetapi menghasilkan mendakan merah bata dengan larutan Benedict (menunjukkan kehadiran glukosa).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Pilihan ini terbalik; glukosa bertindak balas positif terhadap ujian Benedict manakala kanji bertindak balas positif terhadap ujian iodin.</li><li><b>C</b> — Kehadiran protein diuji dengan ujian Biuret (larutan bertukar ungu) manakala lemak diuji dengan ujian emulsi alkohol (membentuk emulsi putih).</li><li><b>D</b> — Sampel Y menghasilkan mendakan merah bata dengan ujian Benedict yang mengesahkan kandungan glukosa, bukannya protein.</li></ul><h5>📌 Ingat</h5><p>Reagen utama ujian makanan: Iodin = kanji (biru tua); Benedict + pemanasan = gula penurun/glukosa (mendakan merah bata); Biuret = protein (warna ungu).</p>",
"<h5>🧠 Konsep utama</h5><p>Tindakan menarik tangan serta-merta apabila tersentuh objek panas merupakan satu contoh tindakan refleks. Tindakan refleks ialah gerak balas automatik dan pantas terhadap sesuatu rangsangan tanpa kawalan sedar otak, yang berfungsi melindungi badan daripada kecederaan parah. Laluan impuls dalam tindakan refleks dikawal oleh saraf tunjang dan dikenali sebagai arka refleks. Reseptor deria haba dan sakit pada kulit mengesan rangsangan dan menjana impuls elektrik. Impuls dihantar sepanjang neuron deria ke saraf tunjang, merentasi sinaps ke neuron perantaraan, kemudian dipindahkan ke neuron motor yang mengaktifkan efektor (otot biseps) untuk mengecut dan menarik tangan.</p><h5>✅ Mengapa jawapan D betul</h5><p>Laluan impuls yang tepat dalam arka refleks tiga neuron ialah Reseptor → neuron deria → neuron perantaraan → neuron motor → efektor.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Urutan neuron terbalik; impuls mesti melalui neuron deria terlebih dahulu sebelum ke neuron perantaraan dan neuron motor.</li><li><b>B</b> — Impuls elektrik sentiasa bermula di reseptor yang mengesan rangsangan dan berakhir di efektor yang menghasilkan gerak balas, bukan sebaliknya.</li><li><b>C</b> — Laluan yang melibatkan pemprosesan otak adalah untuk tindakan terkawal (tindakan sedar), sedangkan tindakan refleks pantas ini dikoordinasikan oleh saraf tunjang.</li></ul><h5>📌 Ingat</h5><p>Laluan arka refleks: Reseptor (kulit) → Neuron deria → Neuron perantaraan (saraf tunjang) → Neuron motor → Efektor (otot mengecut).</p>",
"<h5>🧠 Konsep utama</h5><p>Mata manusia menumpukan sinar cahaya pada retina untuk menghasilkan imej yang jelas. Rabun jauh (miopia) berlaku apabila seseorang dapat melihat objek dekat dengan jelas tetapi objek jauh kelihatan kabur. Kecacatan ini disebabkan oleh bebola mata yang terlalu panjang dari hadapan ke belakang atau kanta mata yang terlalu tebal, menyebabkan sinar cahaya daripada objek jauh tertumpu dan membentuk imej di hadapan retina. Rabun jauh dibetulkan menggunakan kanta cekung (kanta pencapah). Kanta cekung mencapahkan sinar cahaya sebelum memasuki mata supaya imej dapat difokuskan tepat pada retina.</p><h5>✅ Mengapa jawapan C betul</h5><p>Hafiz jelas melihat objek dekat (buku) tetapi kabur melihat objek jauh (papan putih), menandakan dia mengalami rabun jauh yang dibetulkan menggunakan kanta cekung.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Rabun dekat (hipermetropia) ialah keadaan kabur melihat objek dekat, dan kanta cembung menumpukan cahaya untuk membetulkannya.</li><li><b>B</b> — Kanta cembung bersifat menumpukan cahaya; menggunakannya untuk rabun jauh akan menumpukan cahaya lebih ke hadapan retina dan memburukkan keadaan.</li><li><b>D</b> — Rabun dekat tidak dibetulkan dengan kanta cekung kerana kanta cekung akan mencapahkan cahaya lebih jauh ke belakang retina.</li></ul><h5>📌 Ingat</h5><p>Rumusan mudah: Rabun Jauh = Imej di hadapan retina, dibetulkan dengan kanta cekung. Rabun Dekat = Imej di belakang retina, dibetulkan dengan kanta cembung.</p>",
"<h5>🧠 Konsep utama</h5><p>Jantung manusia mempunyai empat ruang: atrium kanan, atrium kiri, ventrikel kanan dan ventrikel kiri. Ruang ventrikel berfungsi mengepam darah keluar daripada jantung ke bahagian badan yang lain. Ventrikel kanan mengepam darah terdeoksigen ke peparu melalui arteri pulmonari (peredaran pulmonari), yang berjarak sangat dekat dan mempunyai rintangan salur darah yang rendah. Sebaliknya, ventrikel kiri bertindak mengepam darah beroksigen keluar melalui aorta ke seluruh anggota badan (peredaran sistemik), iaitu jarak pengaliran yang jauh dengan rintangan salur darah yang tinggi.</p><h5>✅ Mengapa jawapan A betul</h5><p>Dinding otot ventrikel kiri jauh lebih tebal dan berotot kerana ia perlu menghasilkan tekanan hidrostatik darah yang amat tinggi untuk mengepam darah ke seluruh badan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Ventrikel kiri menerima darah beroksigen daripada atrium kiri; atrium kanan yang menerima darah terdeoksigen dari seluruh badan melalui vena kava.</li><li><b>C</b> — Ventrikel kanan yang bertanggungjawab mengepam darah ke peparu, bukan ventrikel kiri.</li><li><b>D</b> — Jantung mengepam darah secara berterusan pada setiap degupan dan ruang ventrikel tidak berfungsi sebagai ruang penyimpanan darah kecemasan.</li></ul><h5>📌 Ingat</h5><p>Perbandingan ketebalan dinding jantung: Ventrikel kiri (paling tebal, ke seluruh badan) > Ventrikel kanan (sederhana, ke peparu) > Atrium (nipis, hanya ke ventrikel).</p>",
"<h5>🧠 Konsep utama</h5><p>Pendebungaan ialah proses pemindahan butir debunga daripada anter ke stigma bunga. Tumbuhan berbunga menyesuaikan struktur bunganya bergantung kepada agen pendebungaan sama ada melalui angin (anemofili) atau serangga/haiwan (entomofili). Bunga yang didebungakan oleh angin seperti pokok padi, jagung dan rumput tidak memerlukan ciri pemikat haiwan. Bunganya biasanya kecil, tidak berbau, berwarna pudar dan tidak menghasilkan nektar. Bagi memastikan pendebungaan berjaya, anter tergantung pada filamen yang panjang di luar bunga untuk melepaskan butir debunga yang banyak, kecil, licin dan ringan, manakala stigma yang berbulu dan terjulur keluar untuk memudahkan penangkapan debunga bawaan tiupan angin.</p><h5>✅ Mengapa jawapan A betul</h5><p>Stigma yang berbulu dan terjulur keluar dari bunga memaksimumkan luas kawasan tangkapan untuk memerangkap butir debunga yang berterbangan di udara.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Ranggi bunga yang berwarna terang dan berbau wangi merupakan ciri penyesuaian bunga yang didebungakan oleh serangga untuk menarik perhatian haiwan tersebut.</li><li><b>C</b> — Penghasilan nektar manis merupakan ganjaran makanan untuk menarik serangga atau burung pendebunga.</li><li><b>D</b> — Butir debunga yang besar, berduri dan melekit direka untuk melekat pada badan serangga, manakala debunga bawaan angin bersaiz kecil, licin dan ringan.</li></ul><h5>📌 Ingat</h5><p>Bunga didebungakan angin: stigma berbulu dan terjulur keluar, debunga kecil, ringan dan banyak, tiada warna cerah atau nektar.</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam reka bentuk sesuatu eksperimen saintifik, satu set kawalan (eksperimen kawalan) disediakan bersama-sama set eksperimen untuk dijadikan piawaian perbandingan yang sah. Pemboleh ubah dimanipulasikan dalam eksperimen ini ialah status kebersihan jari yang menyentuh agar (jari tidak dibasuh vs jari dibasuh dengan sabun), pemboleh ubah bergerak balas ialah bilangan koloni bakteria yang tumbuh, manakala pemboleh ubah dimalarkan ialah jenis dan isi padu agar nutrien steril, suhu pengeraman serta tempoh masa 3 hari. Piring R tidak disentuh, lalu menjadi set kawalan untuk memeriksa sama ada koloni juga tumbuh tanpa sentuhan jari.</p><h5>✅ Mengapa jawapan D betul</h5><p>Piring R ialah kawalan tanpa sentuhan. Jika tiada koloni tumbuh pada R tetapi koloni tumbuh pada P dan Q, pemerhatian itu menyokong kesimpulan bahawa sentuhan jari membawa mikrob ke agar. R juga membantu mengesan pencemaran awal pada agar atau piring.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Piring R tidak disentuh bertujuan untuk mengelakkan pembiakan bakteria, bukannya untuk membiakkan lebih banyak bakteria.</li><li><b>B</b> — Keberkesanan sabun dinilai melalui perbandingan antara piring P (tidak dibasuh) dengan piring Q (dibasuh dengan sabun).</li><li><b>C</b> — Setiap piring Petri ditutup kemas dan diasingkan, tiada perpindahan nutrien antara satu piring dengan piring yang lain.</li></ul><h5>📌 Ingat</h5><p>Set kawalan dikekalkan tanpa faktor manipulasi bagi membuktikan bahawa hasil pemerhatian pada set eksperimen adalah semata-mata disebabkan oleh pemboleh ubah yang diuji.</p>",
"<h5>🧠 Konsep utama</h5><p>Tumbuhan berbunga (angiosperma) dibahagikan kepada dua kelas utama iaitu tumbuhan monokotiledon dan tumbuhan dikotiledon. Tumbuhan monokotiledon mempunyai ciri-ciri morfologi khusus: biji benih dengan satu kotiledon sahaja, sistem akar serabut, urat daun tersusun secara selari, batang kebanyakan tidak berkayu (lembut) serta bilangan kelopak bunga biasanya gandaan tiga. Sebaliknya, tumbuhan dikotiledon mempunyai dua kotiledon dalam biji benih, sistem akar tunjang, daun dengan pertulangan urat jejala, dan batangnya berkayu tegar.</p><h5>✅ Mengapa jawapan B betul</h5><p>Pokok jagung merupakan contoh klasik tumbuhan monokotiledon yang memiliki daun berurat selari, sistem akar serabut dan biji benih dengan satu kotiledon.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Pokok kacang tanah ialah tumbuhan dikotiledon yang mempunyai dua kotiledon, sistem akar tunjang dan daun berurat jejala.</li><li><b>C</b> — Pokok bunga raya ialah tumbuhan dikotiledon dengan daun berurat jejala dan akar tunjang.</li><li><b>D</b> — Pokok rambutan ialah pokok berkayu dikotiledon yang memiliki dua kotiledon dan susunan urat daun berjejala.</li></ul><h5>📌 Ingat</h5><p>Monokotiledon: 1 kotiledon, urat daun selari, akar serabut (contoh: jagung, padi, rumput). Dikotiledon: 2 kotiledon, urat daun jejala, akar tunjang (contoh: bunga raya, rambutan, kekacang).</p>",
"<h5>🧠 Konsep utama</h5><p>Interaksi antara organisma wujud untuk mengekalkan keseimbangan dalam sesuatu ekosistem. Simbiosis ialah hubungan fizikal yang rapat antara dua atau lebih spesies berbeza yang hidup bersama dalam jangka masa panjang. Terdapat tiga jenis simbiosis: mutualisme, komensalisme dan parasitisme. Mutualisme ialah bentuk interaksi di mana kedua-dua pihak yang terlibat saling mendapat faedah dan keuntungan (+/+). Liken merupakan contoh klasik mutualisme antara kulat dengan alga (atau sianobakteria). Alga yang mempunyai klorofil menjalankan proses fotosintesis untuk membekalkan makanan organik kepada kulat. Sebagai balasan, miselium kulat menyerap air dan garam mineral dari persekitaran serta melindungi sel alga daripada kekeringan dan sinaran terik matahari.</p><h5>✅ Mengapa jawapan C betul</h5><p>Hubungan alga dan kulat dalam liken ialah mutualisme kerana kedua-dua organisma mendapat manfaat: alga membekalkan hasil fotosintesis kepada kulat, manakala kulat membekalkan air serta perlindungan kepada alga.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Parasitisme ialah hubungan di mana satu pihak mendapat untung manakala pihak perumah mengalami mudarat atau kerugian (+/-).</li><li><b>B</b> — Komensalisme ialah hubungan yang memberi keuntungan kepada satu spesies sahaja tanpa merugikan atau menguntungkan spesies perumah (+/0).</li><li><b>D</b> — Persaingan berlaku apabila organisma bersaing merebut sumber yang terhad seperti makanan, pasangan atau habitat (-/-).</li></ul><h5>📌 Ingat</h5><p>Mutualisme = kedua-duanya untung (+/+). Contoh penting: Liken (alga + kulat), bakteria <i>Rhizobium</i> dalam nodul akar kekacang, burung tiung dan kerbau.</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam ekosistem, tenaga mengalir melalui aras-aras trofik dalam sesuatu rantai makanan bermula daripada pengeluar kepada pelbagai peringkat pengguna. Mengikut anggaran pemindahan tenaga 10%, hanya kira-kira 10% sahaja daripada jumlah tenaga kimia pada sesuatu aras trofik dipindahkan dan ditukarkan menjadi biojisim organisma pada aras trofik yang seterusnya. Baki sebanyak 90% tenaga hilang ke persekitaran dalam bentuk tenaga haba semasa respirasi sel, perkumuhan, penyahtinjaan, serta melalui bahagian badan yang tidak dimakan atau reput.</p><h5>✅ Mengapa jawapan A betul</h5><p>Pengiraan aliran pemindahan tenaga dari satu aras trofik ke aras berikutnya adalah seperti berikut:<br>1. Aras 1 (Pengeluar / Fitoplankton) = 10 000 kJ<br>2. Aras 2 (Pengguna primer / Zooplankton) = 10% × 10 000 kJ = 1 000 kJ<br>3. Aras 3 (Pengguna sekunder / Ikan bilis) = 10% × 1 000 kJ = 100 kJ<br>4. Aras 4 (Pengguna tertier / Ikan tongkol) = 10% × 100 kJ = 10 kJ.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — 100 kJ ialah nilai tenaga yang diterima oleh pengguna sekunder (ikan bilis), iaitu aras trofik ketiga.</li><li><b>C</b> — 1 000 kJ merupakan nilai tenaga yang dipindahkan kepada pengguna primer (zooplankton) pada aras trofik kedua.</li><li><b>D</b> — 3 000 kJ bukan nilai hasil kiraan pengaliran tenaga berasaskan kecekapan 10% setiap aras trofik.</li></ul><h5>📌 Ingat</h5><p>Setiap lonjakan satu aras trofik, bahagikan nilai tenaga dengan 10 (atau potong satu sifar): 10 000 kJ → 1 000 kJ → 100 kJ → 10 kJ.</p>",
"<h5>🧠 Konsep utama</h5><p>Menurut Teori Kinetik Jirim, jirim wujud dalam tiga fasa keadaan iaitu pepejal, cecair dan gas. Ciri fizikal kemampatan jirim ditentukan oleh susunan zarah dan jarak antara zarah-zarah tersebut. Di dalam pepejal, zarah-zarah tersusun padat dan rapat dalam susunan teratur dengan daya tarikan antara zarah yang sangat kuat, menyebabkan hampir tiada ruang kosong antaranya. Sebaliknya, zarah-zarah gas berada sangat berjauhan antara satu sama lain, bergerak secara rawak pada kelajuan tinggi, dan daya tarikan antara zarah adalah sangat lemah. Kewujudan ruang kosong yang sangat besar antara zarah membolehkan zarah-zarah gas didekatkan apabila dikenakan daya mampatan.</p><h5>✅ Mengapa jawapan D betul</h5><p>Gas mudah dimampatkan kerana terdapat ruang antara zarah yang sangat besar dan kosong, membolehkan zarah-zarah dirapatkan antara satu sama lain apabila diberi tekanan luar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Berat atau jisim zarah tidak menentukan sifat kemampatan; kemampatan bergantung kepada susunan ruang pemisahan antara zarah jirim.</li><li><b>B</b> — Zarah gas sebenarnya bergerak sangat laju dan bertenaga kinetik tinggi berbanding zarah pepejal yang hanya bergetar pada kedudukan tetap.</li><li><b>C</b> — Saiz atom atau molekul sesuatu unsur adalah sama dalam semua fasa; yang berbeza hanyalah jarak fizikal antara zarah tersebut.</li></ul><h5>📌 Ingat</h5><p>Pepejal: tersusun rapat, tiada ruang kosong, tidak boleh dimampatkan. Gas: zarah berjauhan, ruang kosong sangat besar, sangat mudah dimampatkan.</p>",
"<h5>🧠 Konsep utama</h5><p>Argon merupakan unsur bukan logam yang terletak dalam Kumpulan 18 Jadual Berkala, yang dikenali sebagai kumpulan gas adi (gas nadir). Atom gas adi mempunyai susunan elektron valens yang penuh dan stabil, iaitu susunan oktet lapan elektron valens (atau duplet bagi helium). Kestabilan konfigurasi elektron ini menyebabkan gas adi bersifat lengai secara kimia, iaitu tidak cenderung untuk bertindak balas dengan bahan kimia lain. Di dalam mentol berfilamen, filamen tungsten dialirkan arus elektrik sehingga membara putih pada suhu melebihi 2 000 °C. Sekiranya terdapat gas reaktif seperti oksigen, filamen tungsten yang panas membara itu akan teroksida dan terbakar dengan serta-merta.</p><h5>✅ Mengapa jawapan B betul</h5><p>Gas argon digunakan kerana sifat kimianya yang lengai dan stabil, menghalangnya daripada bertindak balas dengan filamen tungsten yang panas lantas memanjangkan jangka hayat mentol.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Argon tidak membekalkan oksigen; kehadiran sebarang oksigen di dalam mentol sebenarnya akan merosakkan dan memusnahkan filamen melalui pembakaran.</li><li><b>C</b> — Gas argon merupakan penebat elektrik dan tidak berfungsi untuk mengalirkan arus elektrik di dalam mentol.</li><li><b>D</b> — Filamen menghasilkan cahaya melalui pemanasan fizikal akibat rintangan elektrik (pijaran), bukannya melalui tindak balas kimia bersama gas argon.</li></ul><h5>📌 Ingat</h5><p>Gas adi (Kumpulan 18): susunan elektron duplet/oktet stabil, lengai secara kimia. Argon = mentol berfilamen, Helium = belon kaji cuaca, Neon = lampu hiasan beriklan.</p>",
"<h5>🧠 Konsep utama</h5><p>Pembakaran ialah tindak balas kimia pantas antara bahan api dengan oksigen yang membebaskan tenaga haba dan cahaya. Tiga komponen dalam segi tiga kebakaran yang wajib ada untuk membolehkan pembakaran berterusan ialah bahan api, haba dan gas oksigen. Udara atmosfera mengandungi kira-kira 21% gas oksigen. Dalam penyiasatan saintifik ini, pemboleh ubah dimanipulasikan ialah isi padu balang gas (250 cm³, 500 cm³ dan 1 000 cm³), pemboleh ubah bergerak balas ialah masa lilin terus menyala (12 s, 25 s dan 49 s), manakala saiz lilin dimalarkan. Semakin besar isi padu balang gas tertutup, semakin besar kuantiti udara dan bekalan oksigen yang terperangkap di dalamnya.</p><h5>✅ Mengapa jawapan C betul</h5><p>Inferens yang paling tepat ialah balang gas yang lebih besar mengandungi kuantiti oksigen yang lebih banyak untuk menyokong proses pembakaran lilin bagi tempoh yang lebih panjang.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Jadual hanya menunjukkan tempoh lilin menyala; jumlah haba yang dibebaskan tidak diukur, jadi pilihan ini tidak menerangkan perbezaan tempoh tersebut.</li><li><b>B</b> — Peratusan komposisi udara awal di dalam semua balang adalah serupa; balang kecil tidak mempunyai kepekatan karbon dioksida awal yang lebih tinggi.</li><li><b>D</b> — Jadual tidak mengukur kadar pembakaran. Masa menyala yang lebih singkat dalam balang kecil lebih sesuai dijelaskan oleh bekalan oksigen terperangkap yang lebih sedikit.</li></ul><h5>📌 Ingat</h5><p>Pembakaran memerlukan gas oksigen. Semakin banyak isi padu udara di dalam bekas tertutup, semakin banyak kuantiti oksigen, maka semakin lama masa pembakaran.</p>",
"<h5>🧠 Konsep utama</h5><p>Penyejatan ialah proses perubahan keadaan jirim cecair kepada gas (wap air) yang berlaku secara perlahan pada permukaan cecair pada sebarang suhu di bawah takat didihnya. Molekul cecair di permukaan yang mempunyai tenaga kinetik yang mencukupi akan mengatasi daya tarikan antara molekul lalu terbebas ke atmosfera. Kadar penyejatan air dipengaruhi oleh empat faktor utama: suhu persekitaran (semakin tinggi suhu, semakin cepat molekul bertenaga), luas permukaan terdedah (semakin luas permukaan, semakin banyak molekul terdedah untuk meruap), pergerakan udara atau angin (angin meniup wap air keluar), dan kelembapan udara (kepekatan wap air di atmosfera).</p><h5>✅ Mengapa jawapan D betul</h5><p>Kelembapan udara yang tinggi bermaksud udara di sekeliling sudah mengandungi kuantiti wap air yang banyak (hampir tepu), menyebabkan kadar penyejatan air menurun dan pakaian lambat kering.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Suhu persekitaran yang tinggi membekalkan lebih banyak tenaga haba kepada zarah air lalu meningkatkan kadar penyejatan.</li><li><b>B</b> — Tiupan angin menggerakkan zarah wap air yang terbebas dan mengekalkan persekitaran kering di atas pakaian lalu meningkatkan penyejatan.</li><li><b>C</b> — Membentangkan pakaian dengan luas menambah luas permukaan air yang terdedah kepada udara lalu mempercepat penyejatan.</li></ul><h5>📌 Ingat</h5><p>Faktor mempercepat penyejatan: Suhu tinggi, angin kencang, luas permukaan besar, kelembapan rendah. Hari mendung/hujan lambat kering kerana kelembapan udara tinggi.</p>",
"<h5>🧠 Konsep utama</h5><p>Nilai pH mengukur darjah keasidan atau kealkalian sesuatu bahan pada skala 0 hingga 14. Nilai pH di bawah 7 menunjukkan bahan berasid, pH 7 mewakili keadaan neutral, manakala pH melebihi 7 menunjukkan bahan beralkali. Kebanyakan tanaman pertanian memerlukan tanah berkeadaan hampir neutral (sekitar pH 6.0 hingga 7.0) untuk penyerapan nutrien yang optimum. Keadaan tanah dengan pH 4.5 adalah sangat berasid, yang boleh merencatkan pertumbuhan akar tanaman. Untuk memulihkan keadaan tanah berasid, proses peneutralan kimia dilakukan dengan menambahkan bahan berbes atau alkali bagi menaikkan nilai pH tanah kembali ke paras optimum.</p><h5>✅ Mengapa jawapan A betul</h5><p>Kapur mati (kalsium hidroksida) merupakan sebatian beralkali yang akan bertindak balas secara peneutralan dengan asid di dalam tanah, lantas menaikkan nilai pH tanah kepada julat yang sesuai.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Baja amonium sulfat bertindak menghasilkan ion berasid di dalam tanah dan akan menurunkan lagi nilai pH tanah tersebut.</li><li><b>C</b> — Cuka mengandungi asid etanoik yang mempunyai pH rendah yang akan meningkatkan lagi keasidan tanah ladang.</li><li><b>D</b> — Garam biasa (natrium klorida) merupakan garam neutral dan tidak berupaya meneutralkan keasidan tanah ladang.</li></ul><h5>📌 Ingat</h5><p>Peneutralan: Asid + Alkali → Garam + Air. Rawatan tanah berasid menggunakan bahan alkali: kapur tohor (kalsium oksida) atau kapur mati (kalsium hidroksida).</p>",
"<h5>🧠 Konsep utama</h5><p>Siri Kereaktifan Logam menyusun unsur-unsur logam mengikut kecenderungan tindak balasnya terhadap oksigen. Karbon diletakkan dalam siri tersebut sebagai rujukan kaedah pengekstrakan: K > Na > Ca > Mg > Al > C > Zn > Fe > Sn > Pb > Cu. Kaedah pengekstrakan sesuatu logam daripada bijih oksidanya bergantung kepada kedudukan relatifnya berbanding karbon. Karbon bertindak sebagai agen penurunan yang dapat menyingkirkan oksigen daripada oksida logam yang berada di bawah karbon dalam siri (seperti zink, besi, timah dan plumbum) melalui pemanasan dalam relau. Namun demikian, logam yang berada di atas karbon (kalium, natrium, kalsium, magnesium, aluminium) mempunyai ikatan yang sangat kuat dengan oksigen dan tidak dapat diturunkan oleh karbon.</p><h5>✅ Mengapa jawapan D betul</h5><p>Aluminium berada di atas karbon dalam siri kereaktifan logam, menyebabkan karbon tidak mampu menyingkirkan oksigen daripada aluminium oksida; oleh itu aluminium diekstrak melalui elektrolisis aluminium oksida yang telah ditulenkan daripada bauksit dan dilarutkan dalam kriolit lebur.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Besi berada di bawah karbon dalam siri kereaktifan, membolehkan bijih besinya diekstrak dengan memanaskannya bersama karbon (kok) dalam relau bagas.</li><li><b>B</b> — Zink berada di bawah karbon dan boleh diekstrak melalui pemanasan zink oksida bersama karbon.</li><li><b>C</b> — Plumbum berada jauh di bawah karbon, jadi oksidanya mudah diturunkan oleh karbon kepada logam plumbum.</li></ul><h5>📌 Ingat</h5><p>Logam di atas Karbon (K, Na, Ca, Mg, Al) diekstrak melalui <b>elektrolisis</b>. Logam di bawah Karbon (Zn, Fe, Sn, Pb) diekstrak melalui <b>penurunan oleh karbon</b>.</p>",
"<h5>🧠 Konsep utama</h5><p>Tindak balas kimia dan proses keterlarutan jirim melibatkan pertukaran tenaga haba antara sistem bahan dengan persekitarannya. Proses eksotermik ialah tindak balas yang membebaskan tenaga haba ke persekitaran. Pembebasan tenaga haba ini menyebabkan suhu persekitaran atau suhu campuran meningkat (bacaan termometer menunjukkan peningkatan, ΔT > 0). Sebaliknya, proses endotermik ialah tindak balas yang menyerap tenaga haba daripada persekitaran, menyebabkan suhu persekitaran menurun (bacaan termometer menunjukkan penurunan, ΔT < 0). Jika bacaan suhu tidak berubah, tiada perubahan suhu bersih yang dapat dikesan; hal ini tidak semestinya bermaksud tiada pemindahan haba langsung.</p><h5>✅ Mengapa jawapan B betul</h5><p>Bahan Q menunjukkan peningkatan suhu akhir daripada 28.0 °C kepada 36.0 °C (peningkatan suhu sebanyak +8.0 °C), membuktikan tenaga haba telah dibebaskan ke dalam persekitaran secara eksotermik.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Bahan P mengalami penurunan suhu daripada 28.0 °C kepada 22.5 °C (−5.5 °C), menunjukkan proses endotermik di mana haba diserap dari air.</li><li><b>C</b> — Bahan R tidak mengalami sebarang perubahan suhu (suhu kekal 28.0 °C), menunjukkan tiada perubahan haba ketara berlaku.</li><li><b>D</b> — Bahan S mengalami penurunan suhu daripada 28.0 °C kepada 24.0 °C (−4.0 °C), menandakan proses endotermik.</li></ul><h5>📌 Ingat</h5><p><b>Eksotermik</b>: haba dibebaskan, suhu campuran <b>meningkat</b>. <b>Endotermik</b>: haba diserap, suhu campuran <b>menurun</b>.</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam litar elektrik selari, beza keupayaan (voltan, V) merentasi setiap cabang selari adalah sama dengan voltan bekalan bateri: V₁ = V₂ = V = 12 V. Arus elektrik yang mengalir melalui setiap cabang bergantung kepada nilai rintangan cabang tersebut mengikut Hukum Ohm (I = V / R). Ammeter disambungkan secara bersiri pada wayar utama litar sebelum titik percabangan, maka ammeter menyukat jumlah arus keseluruhan (I_jumlah) litar. Jumlah arus litar selari ialah hasil tambah arus pada semua cabang: I_jumlah = I₁ + I₂. Secara alternatif, rintangan berkesan (R) dihitung melalui rumus selari: 1/R = 1/(6 Ω) + 1/(3 Ω) = 1/6 Ω⁻¹ + 1/3 Ω⁻¹ = 1/2 Ω⁻¹, memberikan R = 2 Ω.</p><h5>✅ Mengapa jawapan D betul</h5><p>Arus pada cabang perintang 6 Ω ialah I₁ = 12 V ÷ 6 Ω = 2 A. Arus pada cabang perintang 3 Ω ialah I₂ = 12 V ÷ 3 Ω = 4 A. Jumlah arus yang disukat oleh ammeter ialah I_jumlah = 2 A + 4 A = 6.0 A (atau melalui rintangan berkesan: I = 12 V ÷ 2 Ω = 6.0 A).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Nilai 1.3 A terhasil sekiranya tersilap menganggap litar ini disambung secara siri (I = 12 V ÷ (6 + 3) Ω = 1.33 A).</li><li><b>B</b> — Nilai 2.0 A hanyalah arus yang mengalir melalui cabang perintang 6 Ω sahaja, bukan arus utama yang disukat ammeter.</li><li><b>C</b> — Nilai 4.0 A hanyalah arus yang mengalir merentasi cabang perintang 3 Ω sahaja.</li></ul><h5>📌 Ingat</h5><p>Litar selari: voltan cabang sama (V = 12 V), arus bercabang bertambah (I = I₁ + I₂), ammeter pada litar utama menyukat jumlah arus keseluruhan.</p>",
"<h5>🧠 Konsep utama</h5><p>Elektrostatik ialah fenomena kewujudan cas elektrik pegun pada sesuatu bahan. Atom terdiri daripada nukleus yang mengandungi proton (bercas positif) dan neutron (neutral) yang diikat kuat oleh daya nuklear yang amat teguh, serta elektron (bercas negatif) yang berputar di sekeliling nukleus. Zarah yang boleh berpindah antara bahan semasa geseran mekanikal hanyalah elektron kerana ia berada pada petala luar atom. Proton tidak boleh berpindah kerana terikat kukuh di dalam nukleus. Apabila dua penebat berlainan digosok bersama, bahan yang mempunyai keupayaan menarik elektron lebih tinggi akan menerima elektron dan menjadi bercas negatif, manakala bahan yang kehilangan elektron akan berlebihan cas positif lalu menjadi bercas positif.</p><h5>✅ Mengapa jawapan C betul</h5><p>Rod politena menjadi bercas negatif kerana elektron telah berpindah daripada kain wul ke rod politena semasa gosokan, menjadikan rod berlebihan elektron negatif.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Proton terikat kuat di dalam nukleus atom dan tidak boleh dipindahkan melalui proses geseran fizikal.</li><li><b>B</b> — Pemindahan cas elektrik pegun hanya melibatkan pergerakan zarah elektron, proton tidak sekali-kali berpindah dari nukleus.</li><li><b>D</b> — Jika elektron berpindah keluar dari rod ke kain wul, rod akan kekurangan elektron dan menjadi bercas positif, bukan negatif.</li></ul><h5>📌 Ingat</h5><p>Hanya <b>elektron</b> yang berpindah semasa geseran! Menerima elektron = bercas negatif. Kehilangan elektron = bercas positif. Proton tidak bergerak.</p>",
"<h5>🧠 Konsep utama</h5><p>Jisim dan berat merupakan dua konsep fizik yang berbeza tetapi sering dikelirukan. Jisim (m) ialah kuantiti jirim yang terkandung di dalam sesuatu jasad. Jisim ialah kuantiti skalar yang nilainya kekal malar di mana-mana jua lokasi di alam semesta dan diukur dalam unit kilogram (kg). Sebaliknya, berat (W) ialah daya tindakan graviti yang bertindak ke atas sesuatu jasad berjisim. Berat ialah kuantiti vektor yang bergantung kepada kekuatan medan graviti (g) setempat, dihitung dengan rumus W = m × g dan disukat dalam unit Newton (N).</p><h5>✅ Mengapa jawapan A betul</h5><p>Jisim angkasawan kekal tidak berubah di Bulan iaitu 60 kg. Berat angkasawan di Bulan dihitung menggunakan rumus W = m × g = 60 kg × 1.6 N kg⁻¹ = 96 N.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Jisim tidak berkurang kepada 10 kg; jisim ialah sifat intrinsik jirim yang sentiasa malar walau di mana objek berada.</li><li><b>C</b> — Nilai berat 600 N merupakan berat angkasawan semasa berada di permukaan Bumi (60 kg × 10 N kg⁻¹), bukan di Bulan.</li><li><b>D</b> — Kedua-dua nilai salah kerana jisim objek kekal 60 kg dan berat yang terhasil di Bulan adalah 96 N.</li></ul><h5>📌 Ingat</h5><p><b>Jisim (kg) sentiasa malar</b> di mana-mana. <b>Berat (N) berubah</b> mengikut graviti setempat dengan rumus W = m × g.</p>",
"<h5>🧠 Konsep utama</h5><p>Semua objek panas membebaskan haba ke persekitaran secara sinaran terma dalam bentuk gelombang inframerah tanpa memerlukan medium perantaraan. Kadar pemancaran haba secara sinaran dipengaruhi oleh sifat warna dan tekstur permukaan objek tersebut. Permukaan yang gelap, hitam dan pudar merupakan pemancar haba serta penyerap haba yang sangat cekap dan pantas. Sebaliknya, permukaan yang cerah, putih dan berkilat merupakan pemancar haba yang lemah (dan pemantul haba yang baik). Dalam eksperimen ini, kedua-dua tin mengandungi air panas dengan isi padu dan suhu awal yang sama (80 °C). Tin yang mengalami penurunan suhu yang lebih besar menunjukkan bahawa ia telah memancarkan haba ke persekitaran dengan kadar yang lebih tinggi.</p><h5>✅ Mengapa jawapan B betul</h5><p>Suhu air dalam tin hitam pudar turun sebanyak 24 °C (80 °C − 56 °C = 24 °C), manakala tin putih berkilat hanya turun 12 °C (80 °C − 68 °C = 12 °C). Ini membuktikan permukaan hitam pudar ialah pemancar haba yang lebih baik berbanding permukaan putih berkilat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Permukaan putih berkilat mengalami penurunan suhu yang lebih rendah, membuktikan ia membebaskan haba lebih perlahan (pemancar haba lemah).</li><li><b>C</b> — Perbezaan suhu akhir yang ketara membuktikan bahawa jenis dan warna permukaan memberi kesan langsung kepada kadar kehilangan haba.</li><li><b>D</b> — Eksperimen ini mengkaji proses kehilangan dan pemancaran haba dari tin ke udara sejuk persekitaran, bukannya proses penyerapan haba oleh air.</li></ul><h5>📌 Ingat</h5><p>Objek hitam pudar: pemancar dan penyerap haba yang baik. Objek putih berkilat: pemancar dan penyerap haba yang lemah, tetapi pemantul haba yang baik.</p>",
"<h5>🧠 Konsep utama</h5><p>Pembiasan cahaya ialah fenomena pembengkokan arah perambatan sinar cahaya apabila merambat merentasi sempadan dua medium yang berbeza ketumpatan optik. Perubahan arah ini berlaku kerana kelajuan cahaya berubah apabila memasuki medium yang berlainan ketumpatan. Air mempunyai ketumpatan optik yang lebih tinggi daripada udara. Apabila sinar cahaya daripada dasar kolam bergerak keluar dari air (medium lebih tumpat) ke udara (medium kurang tumpat), kelajuan cahaya bertambah dan sinar cahaya dibiaskan menjauhi garis normal. Apabila sinar biasan ini memasuki mata pemerhati, otak memproyeksikan sinar tersebut secara lurus ke belakang, menghasilkan imej maya dasar kolam pada kedudukan yang lebih tinggi daripada kedudukan sebenarnya (kedalaman ketara lebih kecil daripada kedalaman sebenar).</p><h5>✅ Mengapa jawapan C betul</h5><p>Fenomena dasar kolam kelihatan lebih cetek berlaku akibat pembiasan cahaya apabila cahaya merambat dari air yang lebih tumpat ke udara yang kurang tumpat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Pantulan cahaya ialah pembalikan sinar cahaya pada permukaan sempadan dan tidak menyebabkan perubahan kedalaman ketara dasar kolam.</li><li><b>B</b> — Penyebaran cahaya ialah pengasingan cahaya putih kepada spektrum warna pelangi akibat perbezaan kelajuan warna dalam medium.</li><li><b>D</b> — Penyerakan cahaya ialah penyebaran cahaya ke semua arah oleh zarah halus di atmosfera, seperti fenomena langit kelihatan biru.</li></ul><h5>📌 Ingat</h5><p>Dari medium lebih tumpat ke kurang tumpat (air → udara): sinar cahaya membias <b>menjauhi normal</b>, menyebabkan dasar air kelihatan lebih cetek.</p>",
"<h5>🧠 Konsep utama</h5><p>Gelombang bunyi ialah gelombang mekanikal membujur yang dihasilkan oleh objek yang bergetar dan memerlukan medium fizikal untuk merambat. Frekuensi gelombang bunyi ditakrifkan sebagai bilangan getaran lengkap sesaat dan disukat dalam unit Hertz (Hz). Sistem pendengaran telinga manusia mempunyai julat frekuensi yang terhad untuk mengesan getaran gegendang telinga. Julat frekuensi audio yang mampu dikesan oleh pendengaran manusia normal dikenali sebagai julat pendengaran audio, iaitu merangkumi frekuensi dari 20 Hz sehingga 20 000 Hz (atau 20 kHz). Bunyi berfrekuensi di bawah 20 Hz dikenali sebagai gelombang infrasonik, manakala gelombang melebihi 20 000 Hz dikenali sebagai gelombang ultrasonik.</p><h5>✅ Mengapa jawapan B betul</h5><p>Julat frekuensi pendengaran telinga manusia normal yang tepat adalah antara 20 Hz hingga 20 000 Hz.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Julat 2 Hz hingga 2 000 Hz tidak tepat kerana manusia tidak dapat mendengar bunyi bawah 20 Hz dan masih boleh mendengar bunyi melebihi 2 000 Hz.</li><li><b>C</b> — Telinga manusia tidak dapat mengesan getaran frekuensi sehingga 200 000 Hz kerana had maksimum pendengaran manusia hanyalah 20 000 Hz.</li><li><b>D</b> — Julat 20 kHz hingga 200 kHz merupakan spektrum ultrasonik yang hanya boleh didengar oleh sesetengah haiwan seperti kelawar dan ikan lumba-lumba.</li></ul><h5>📌 Ingat</h5><p>Julat pendengaran manusia: 20 Hz – 20 000 Hz (20 kHz). Bawah 20 Hz = infrasonik (gajah, paus); Atas 20 000 Hz = ultrasonik (kelawar, lumba-lumba).</p>",
"<h5>🧠 Konsep utama</h5><p>Tenaga keupayaan graviti ialah tenaga yang disimpan dalam sesuatu objek disebabkan oleh ketinggian atau kedudukannya dalam suatu medan graviti. Apabila suatu objek diangkat tegak melawan arah daya tarikan graviti Bumi, kerja mekanikal dilakukan ke atas objek tersebut. Bagi pengiraan ini, pertambahan tenaga keupayaan graviti objek sama dengan kerja yang dilakukan melawan graviti, iaitu m × g × h. Tenaga keupayaan graviti (E_p) dihitung menggunakan rumus: E_p = m × g × h, di mana m ialah jisim objek dalam unit kilogram (kg), g ialah kekuatan medan graviti dalam unit N kg⁻¹ (atau m s⁻²), dan h ialah ketinggian tegak objek dinaikkan dalam unit meter (m). Unit SI bagi tenaga ialah Joule (J).</p><h5>✅ Mengapa jawapan C betul</h5><p>Pengiraan tenaga keupayaan graviti buku dengan menggantikan nilai yang diberi ke dalam rumus:<br>E_p = m × g × h = 2 kg × 10 N kg⁻¹ × 1.5 m = 30 J.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Nilai 3 J diperoleh akibat tertinggal mendarabkan dengan nilai graviti g (iaitu hanya mengira m × h = 2 × 1.5 = 3).</li><li><b>B</b> — Nilai 15 J diperoleh sekiranya terlupa mendarabkan jisim objek (iaitu hanya g × h = 10 × 1.5 = 15).</li><li><b>D</b> — Nilai 300 J diperoleh jika tersilap menggunakan nilai ketinggian sebagai 15 m dan bukannya 1.5 m.</li></ul><h5>📌 Ingat</h5><p>Rumus Tenaga Keupayaan Graviti: <b>E_p = mgh</b>. Pastikan unit piawai digunakan: jisim (kg), graviti (N kg⁻¹), tinggi (m), dan tenaga (J).</p>",
"<h5>🧠 Konsep utama</h5><p>Pereputan radioaktif ialah proses rawak dan spontan di mana nukleus atom yang tidak stabil membebaskan zarah bertenaga atau sinaran radioaktif untuk menjadi nukleus yang lebih stabil. Kadar reputan sesuatu radioisotop diukur melalui separuh hayatnya. Separuh hayat (t_½) ditakrifkan sebagai masa yang diambil untuk separuh daripada bilangan nukleus atom radioaktif asal mereput, atau masa untuk jisim sampel radioaktif berkurang menjadi separuh daripada jisim asalnya. Bagi setiap selang masa satu separuh hayat yang berlalu, kuantiti bahan radioaktif yang belum mereput akan menjadi separuh (50%) daripada kuantiti sebelumnya.</p><h5>✅ Mengapa jawapan A betul</h5><p>Bilangan kitaran separuh hayat yang dialami dalam tempoh 24 hari: n = 24 hari ÷ 8 hari = 3 kali separuh hayat. Pengurangan jisim langkah demi langkah:<br>• Asal (0 hari) = 80 g<br>• Selepas 8 hari (1 kitaran) = 80 g ÷ 2 = 40 g<br>• Selepas 16 hari (2 kitaran) = 40 g ÷ 2 = 20 g<br>• Selepas 24 hari (3 kitaran) = 20 g ÷ 2 = 10 g. Maka jisim bahan yang belum mereput ialah 10 g.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — 20 g ialah baki jisim bahan selepas 16 hari (iaitu selepas melalui 2 kitaran separuh hayat).</li><li><b>C</b> — 26.7 g diperoleh jika tersilap membahagi jisim asal secara linear dengan 3 kitaran (80 ÷ 3), sedangkan reputan radioaktif berlaku secara eksponen.</li><li><b>D</b> — 40 g ialah baki jisim sampel selepas 8 hari (iaitu selepas hanya 1 kitaran separuh hayat).</li></ul><h5>📌 Ingat</h5><p>Separuh hayat = bahagi 2 setiap selang masa t_½. Cari bilangan kitaran n = Jumlah masa ÷ Separuh hayat. Bagi n = 3: 80 g → 40 g → 20 g → 10 g.</p>",
"<h5>🧠 Konsep utama</h5><p>Kerak Bumi dibina daripada pelbagai jenis batuan yang dikelaskan kepada tiga kumpulan utama berdasarkan mod pembentukannya: batuan igneus, batuan enapan (sedimen), dan batuan metamorfik. Batuan igneus terhasil daripada proses penyejukan dan pemejalan magma (batuan cair di bawah kerak Bumi) atau lava (magma yang mengalir keluar ke permukaan Bumi). Apabila magma menyejuk secara perlahan jauh di dalam kerak Bumi, kristal mineral terbentuk dengan saiz yang kasar membentuk batuan igneus rejahan seperti granit. Jika lava menyejuk dengan pantas di permukaan Bumi semasa letusan gunung berapi, kristal mineral halus terbentuk menghasilkan batuan igneus terobosan seperti basalt.</p><h5>✅ Mengapa jawapan D betul</h5><p>Granit ialah batuan igneus yang terbentuk secara khusus daripada proses penyejukan dan pembekuan batuan lebur (magma) di bawah permukaan kerak Bumi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Pemampatan dan penyimenan lapisan sedimen secara berperingkat menghasilkan batuan enapan seperti batu pasir dan syal.</li><li><b>B</b> — Perubahan struktur batuan sedia ada akibat pendedahan kepada suhu yang amat tinggi dan tekanan kuat menghasilkan batuan metamorfik seperti marmar.</li><li><b>C</b> — Pengumpulan cengkerang haiwan marin dan kalsium karbonat di dasar laut membentuk batuan enapan organik seperti batu kapur.</li></ul><h5>📌 Ingat</h5><p>Kitaran Batuan: <b>Igneus</b> = magma/lava membeku (cth. granit, basalt). <b>Enapan</b> = pemendapan dan pemampatan zarah (cth. batu pasir). <b>Metamorfik</b> = perubahan haba dan tekanan tinggi (cth. marmar).</p>",
"<h5>🧠 Konsep utama</h5><p>Satelit buatan yang mengelilingi Bumi bergerak pada laluan orbit tertentu di bawah pengaruh daya tarikan graviti Bumi. Satelit geopegun mengorbit Bumi pada satah khatulistiwa pada ketinggian kira-kira 35 786 km dari permukaan Bumi. Orbit ini direka dengan teliti supaya tempoh orbit satelit mengelilingi Bumi adalah tepat 24 jam (satu hari Bumi), dan arah peredarannya adalah sama dengan arah putaran Bumi pada paksinya (dari barat ke timur). Halaju sudut satelit yang sama persis dengan halaju putaran Bumi membolehkan satelit sentiasa berada pada kedudukan geografi yang sama di atas muka Bumi.</p><h5>✅ Mengapa jawapan B betul</h5><p>Satelit komunikasi MEASAT kelihatan seolah-olah pegun di langit kerana tempoh peredaran orbitnya adalah tepat 24 jam, iaitu sama dengan tempoh putaran Bumi pada paksinya.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Satelit sebenarnya sedang mengorbit Bumi secara berterusan pada kelajuan sangat tinggi (kira-kira 3 km s⁻¹); ia hanya kelihatan pegun secara relatif dari permukaan Bumi.</li><li><b>C</b> — Satelit kekal berada dalam pengaruh medan graviti Bumi; daya graviti Bumi inilah yang bertindak sebagai daya memusat yang mengekalkan orbit satelit.</li><li><b>D</b> — Satelit yang mengorbit dari kutub ke kutub dikenali sebagai satelit orbit kutub (contohnya satelit penderiaan jauh kaji cuaca), bukan satelit geopegun.</li></ul><h5>📌 Ingat</h5><p>Satelit <b>geopegun</b>: berada di atas khatulistiwa, tempoh orbit <b>24 jam</b> (sama dengan putaran Bumi), kedudukannya tetap relatif kepada titik di Bumi (cth. satelit MEASAT).</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam Sistem Suria kita, lapan buah planet beredar mengelilingi Matahari dalam orbit berbentuk elips di bawah kawalan daya tarikan graviti Matahari. Daya graviti antara Matahari dengan planet berkurang apabila jarak pemisahan antara kedua-duanya bertambah. Mengikut Hukum Gerakan Planet (Hukum Kepler Ketiga), planet yang terletak semakin jauh daripada Matahari bergerak merentasi lilitan orbit yang jauh lebih besar dan panjang. Di samping itu, daya graviti Matahari yang semakin lemah menyebabkan halaju linear orbit planet menjadi lebih perlahan. Kombinasi laluan orbit yang lebih panjang serta kelajuan orbit yang lebih perlahan ini menyebabkan masa yang diperlukan untuk melengkapkan satu pusingan orbit (tempoh orbit) meningkat secara ketara.</p><h5>✅ Mengapa jawapan C betul</h5><p>Data jadual menunjukkan bahawa apabila jarak purata dari Matahari bertambah (58 → 150 → 778 → 4 500 juta km), tempoh orbit planet juga semakin bertambah (0.24 → 1.0 → 11.9 → 164.8 tahun Bumi), membuktikan semakin jauh planet dari Matahari, semakin panjang tempoh orbitnya.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Pilihan ini menyatakan hubungan yang bertentangan secara langsung dengan tren peningkatan nilai data pada jadual.</li><li><b>B</b> — Data jadual membuktikan wujud korelasi yang sangat kuat dan nyata antara jarak dari Matahari dengan tempoh orbit planet.</li><li><b>D</b> — Nilai tempoh orbit setiap planet adalah sangat berbeza-beza (Utarid mengambil masa hanya beberapa bulan, manakala Neptun mengambil masa 164.8 tahun Bumi).</li></ul><h5>📌 Ingat</h5><p>Semakin jauh kedudukan planet dari Matahari: daya tarikan graviti semakin lemah, kelajuan orbit semakin perlahan, dan <b>tempoh orbit semakin panjang</b>.</p>"]};
